/// Copy used for foreground OS notifications. OS surfaces (including the lock
/// screen) are not authenticated Masanawa Activity. No provider-supplied text,
/// actor display names or amounts may be interpolated into this preview.
///
/// Backend Talk previews are generated by talk_notifications/policy.ts; keep
/// equivalent generic semantics when updating either side. Unknown or future
/// event types fail closed to an uninformative, tappable update.
class PrivatePushPreview {
  const PrivatePushPreview(this.title, this.body);
  final String title;
  final String body;
}

PrivatePushPreview privatePushPreview(Map<String, dynamic> data) {
  return switch (data['kind']) {
    'talk_invitation' => const PrivatePushPreview(
        'Talk invitation', 'You have a Talk invitation.'),
    'raise_hand_accepted' => const PrivatePushPreview(
        "You're invited to speak", 'The Host accepted your request to speak.'),
    'raise_hand_declined' => const PrivatePushPreview(
        'Speaker request update', "The Host couldn't add you as a speaker this time."),
    'ai_seat_sponsored' => const PrivatePushPreview(
        'AI Seat sponsored', 'A sponsored AI Seat is waiting for your decision.'),
    'ai_seat_accepted' => const PrivatePushPreview(
        'AI Seat accepted', 'The Host accepted your sponsored AI Seat.'),
    'ai_seat_declined' => const PrivatePushPreview(
        'AI Seat not admitted', 'Your AI Seat invitation has an update.'),
    'followed_host_live' => const PrivatePushPreview(
        'A Host you follow is live', 'A new Talk has started.'),
    'replay_ready' => const PrivatePushPreview(
        'Replay ready', 'A Talk replay is now available.'),
    'gift_received' => const PrivatePushPreview(
        'You received a gift', 'You received a gift in a Talk.'),
    'earning_available' => const PrivatePushPreview(
        'New earnings', 'Your Talk earnings have an update.'),
    'platform_notice' => const PrivatePushPreview(
        'Masanawa', "There's an important update about your Talk activity."),
    _ => const PrivatePushPreview('Masanawa', 'You have a new update.'),
  };
}
